import json

from textstats.cli import main


def test_plain():
    assert main(["b a b"]) == "a=1\nb=2"


def test_json_flag():
    assert json.loads(main(["--json", "b a b"])) == {"a": 1, "b": 2}


def test_counts_ignore_case():
    assert main(["A a"]) == "a=2"

steps.action:
cd /repo && cat > textstats/cli.py << 'EOF'
import json
import sys


def main():
    args = sys.argv[1:]
    text = ""
    json_output = False

    # Parse arguments: handle --json flag
    i = 0
    while i < len(args):
        if args[i] == "--json":
            json_output = True
            i += 1
        else:
            text += args[i] + " "
            i += 1

    text = text.strip()

    # Count character frequencies (alphabetic characters, case-insensitive)
    counts = {}
    for char in text.lower():
        if char.isalpha():
            counts[char] = counts.get(char, 0) + 1

    # Output results
    if json_output:
        result = {k: v for k, v in sorted(counts.items())}
        print(json.dumps(result))
    else:
        parts = []
        for char in sorted(counts.keys()):
            parts.append(f"{char}={counts[char]}")
        print("\n".join(parts))


if __name__ == "__main__":
    main()
